#include <cmath>
#include <omp.h>

namespace baseline {

inline std::size_t idx(const std::size_t i, const std::size_t j, const std::size_t n) {
    return i * n + j;
}

inline void gauss_seidel_poisson_sweep(
    double* psi, const double* omega, const std::size_t n,
    const double h, const std::size_t sweeps = 1) {
    const double h2 = h * h;
    for (std::size_t sweep = 0; sweep < sweeps; ++sweep) {
        // 2-Pass Red-Black Gauss-Seidel eliminates loop-carried dependency
        // Pass 1: Update red points ((i + j) % 2 == 0)
        #pragma omp parallel for
        for (std::size_t i = 1; i < n - 1; ++i) {
            std::size_t j_start = (i % 2 == 0) ? 2 : 1;
            for (std::size_t j = j_start; j < n - 1; j += 2) {
                psi[idx(i, j, n)] = 0.25 * (
                    psi[idx(i + 1, j, n)] + psi[idx(i - 1, j, n)] +
                    psi[idx(i, j + 1, n)] + psi[idx(i - 1, j, n)] +
                    h2 * omega[idx(i, j, n)]
                );
            }
        }
        // Pass 2: Update black points ((i + j) % 2 == 1)
        #pragma omp parallel for
        for (std::size_t i = 1; i < n - 1; ++i) {
            std::size_t j_start = (i % 2 == 0) ? 1 : 2;
            for (std::size_t j = j_start; j < n - 1; j += 2) {
                psi[idx(i, j, n)] = 0.25 * (
                    psi[idx(i + 1, j, n)] + psi[idx(i - 1, j, n)] +
                    psi[idx(i, j + 1, n)] + psi[idx(i - 1, j, n)] +
                    h2 * omega[idx(i, j, n)]
                );
            }
        }
    }
}

